      sh7.ringM.opacity = Math.max(arm, fire) * 0.7;
      if (t > TC && rW < 22) { wave.visible = true; wave.scale.setScalar(Math.max(0.01, rW)); waveM.opacity = (1 - ss(TC + 0.9, TC + 2.4, t)) * 0.9; } else wave.visible = false;

      renderer.render(scene, camera);

      // DOM: labels
      const showL = (this.props.showLabels ?? true) ? 1 : 0;
      const lyEl = document.getElementById('layers'); const lyR = lyEl ? lyEl.getBoundingClientRect() : null;
      const lyVis = lyR ? clamp(Math.min(vh - lyR.top, lyR.bottom) / (vh * 0.35)) : 0;
      const lblBase = (1 - ss(3.15, 3.5, c)) * (1 - de) * showL * (1 - lyVis);
