        v3.copy(N[k].top); v3.y += 0.32; v3.project(camera);
        const x = (v3.x * 0.5 + 0.5) * rw, y = (-v3.y * 0.5 + 0.5) * rh;
        if (!isFinite(x) || !isFinite(y)) { el.style.opacity = '0'; return; }
        let o = lblBase * (v3.z < 1 ? 1 : 0);
        if (k !== 6 && k !== 7) o *= 1 - arm * 0.8;
        if (![2,6,7].includes(k)) o *= 1 - proof * 0.85;
        if (x > innerWidth * 0.54 && c > 0.6 && c < 3.4) o *= 0.08;
el.style.transform = `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px)`;
        const tb = el.children[1]; if (tb) tb.style.transform = x > rw - 190 ? 'translateX(calc(-100% - 24px))' : 'none';
        if (avoid.length && tb) { const bx = tb.getBoundingClientRect(); if (hit(bx) || hit({ left: x - 6, right: x + 6, top: y - 6, bottom: y + 6 }) || bx.right > rw - 8) o = 0; }
        el.style.opacity = o.toFixed(3);
        const dot = this['ld' + i].current; const hh = heat[k];
        let dc = hh > 0.35 ? '#ff6a3d' : '#8a94a3';
        if (k === 6) dc = t > TC && calm < 1 ? '#2bb8ff' : ltv > 80 ? '#ff6a3d' : '#2bb8ff';
        if (k === 7 && t > TC) dc = '#2bb8ff';
        if (proof > 0.5) dc = '#e9edf2';
