        const hot = hh > 0.35;
        if (proof > 0.5) {
          const pt = { 2: 'TRIGGER MET · LTV 82.42%', 6: 'VERIFIED · LTV 82.42% → 78.12%', 7: 'REPAY 1,086.50 USDC · FORK TX' };
          setTxt(i, pt[k] || '', '#e9edf2');
        } else if (k === 1) setTxt(i, hot ? 'PRICE SHOCK' : 'COLLATERAL', hot ? '#ff6a3d' : '#8a94a3');
        else if (k === 2) setTxt(i, hot ? 'SHOCK −9.0%' : 'weETH / ETH', hot ? '#ff6a3d' : '#8a94a3');
        else if (k === 5) setTxt(i, hot ? 'UNDER STRESS' : 'LENDING MARKET', hot ? '#ff6a3d' : '#8a94a3');
